const commits = $input.first().json.body?.commits || [];
const changedFiles = [];

for (const commit of commits) {
  changedFiles.push(...(commit.added || []));
  changedFiles.push(...(commit.modified || []));
}

const categories = {
  scenes: changedFiles.filter(f => f.includes('scenes/')),
  assets: changedFiles.filter(f => f.includes('assets/')),
  config: changedFiles.filter(f => f.includes('config/')),
  tests: changedFiles.filter(f => f.includes('.test.')),
  package: changedFiles.filter(f => f === 'package.json')
};

const actions = [];
if (categories.scenes.length > 0) actions.push('run_tests', 'build_check');
if (categories.assets.length > 0) actions.push('validate_assets');
if (categories.package.length > 0) actions.push('install_deps', 'security_audit');
if (changedFiles.length > 0) actions.push('deploy_preview');

return {
  changedFiles,
  categories,
  actions,
  branch: $input.first().json.body?.ref?.replace('refs/heads/', '') || 'main',
  commitMessage: commits[0]?.message || 'No message'
};

const report = {
  timestamp: new Date().toISOString(),
  project: 'NovaLearning Letter Recognition',
  sprint: 'MVP A-F',
  checks: {
    deployment: { status: 'checking', url: 'https://novalearning-games.vercel.app' },
    assets: { sprites: '0/6', audio: '0/18' },
    performance: { js_bundle: 'N/A', load_time: 'N/A' },
    tests: { passed: 0, failed: 0, coverage: '0%' }
  },
  nextMilestones: [
    'Complete BootScene implementation',
    'Generate 6 Ubuntu Buddy sprites',
    'Integrate audio pipeline'
  ]
};

return report;

