const request = $input.first().json;
const character = request.body?.character || 'all';

const CHARACTERS = [
  { name: 'aardvark', letter: 'A', color: '#E85D04', value: 'Achievement' },
  { name: 'baboon', letter: 'B', color: '#4CC9F0', value: 'Bravery' },
  { name: 'cheetah', letter: 'C', color: '#F4A261', value: 'Champions' },
  { name: 'dung-beetle', letter: 'D', color: '#8D6748', value: 'Determination' },
  { name: 'elephant', letter: 'E', color: '#52B788', value: 'Empathy' },
  { name: 'flamingo', letter: 'F', color: '#FF6B9D', value: 'Family' }
];

const toGenerate = character === 'all' ? CHARACTERS : CHARACTERS.filter(c => c.name === character);

return {
  characters: toGenerate,
  specs: {
    dimensions: '512x512',
    frames: 8,
    layout: '4x2',
    format: 'PNG',
    maxSizeKB: 500
  },
  outputPath: 'src/assets/sprites/animals/',
  requestedAt: new Date().toISOString()
};

const results = $input.first().json;
const validations = [];

for (const asset of results.generatedAssets || []) {
  const validation = {
    file: asset.filename,
    checks: {
      exists: asset.success,
      dimensions: asset.dimensions === '512x512' ? 'PASS' : 'FAIL',
      size: asset.sizeKB < 500 ? 'PASS' : 'FAIL',
      format: asset.format === 'PNG' ? 'PASS' : 'FAIL'
    },
    overall: 'PASS'
  };

  if (Object.values(validation.checks).includes('FAIL')) {
    validation.overall = 'FAIL';
  }

  validations.push(validation);
}

const allPassed = validations.every(v => v.overall === 'PASS');

return {
  validations,
  summary: {
    total: validations.length,
    passed: validations.filter(v => v.overall === 'PASS').length,
    failed: validations.filter(v => v.overall === 'FAIL').length
  },
  allPassed
};

